package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    attribute count : Integer := 0;
    attribute previousPressed : Boolean := false;
    perform action tick {
      first start;
      then if ((io_0) and ((not previousPressed))) {
        first start;
        then assign count := count + 1;
        then assign previousPressed := io_0;
      } else {
        first start;
        then assign previousPressed := io_0;
      }
    }
    out attribute io_1 : Integer = count;
    out attribute io_2 : Boolean = count != 2 * RealFunctions::floor(count / 2);
  }
  part system : Controller;
}
